  3→//! Executes resolved steps with proper environment handling,
  4→//! interpolation, and hook execution.
  5→
  6→use crate::config::interpolation::{resolve_string, InterpolationContext};
  7→use crate::error::{BivvyError, Result};
  8→use crate::shell::{execute, execute_streaming, CommandOptions, OutputCallback};
  9→use crate::steps::completed_check::{run_check, run_check_interpolated, CheckResult};
 10→use crate::steps::resolved::ResolvedStep;
 11→use std::collections::HashMap;
 12→use std::path::Path;
 13→use std::time::Duration;
 14→
 15→/// Status of a step in the workflow.
 16→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 17→pub enum StepStatus {
 18→    /// Step is waiting to run.
 19→    Pending,
 20→
 21→    /// Step is currently executing.
 22→    Running,
 23→
 24→    /// Step completed successfully.
 25→    Completed,
 26→
 27→    /// Step failed.
 28→    Failed,
 29→
 30→    /// Step was skipped (already complete or dependency failed).
 31→    Skipped,
 32→}
 33→
 34→impl StepStatus {
 35→    /// Check if this is a terminal state (no more changes expected).
 36→    pub fn is_terminal(&self) -> bool {
 37→        matches!(
 38→            self,
 39→            StepStatus::Completed | StepStatus::Failed | StepStatus::Skipped
 40→        )
 41→    }
 42→
 43→    /// Get a display character for this status.
 44→    pub fn display_char(&self) -> char {
 45→        match self {
 46→            StepStatus::Pending => '○',
 47→            StepStatus::Running => '◉',
 48→            StepStatus::Completed => '✓',
 49→            StepStatus::Failed => '✗',
 50→            StepStatus::Skipped => '⊘',
 51→        }
 52→    }
 53→}
 54→
 55→impl std::fmt::Display for StepStatus {
 56→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 57→        let s = match self {
 58→            StepStatus::Pending => "pending",
 59→            StepStatus::Running => "running",
 60→            StepStatus::Completed => "completed",
 61→            StepStatus::Failed => "failed",
 62→            StepStatus::Skipped => "skipped",
 63→        };
 64→        write!(f, "{}", s)
 65→    }
 66→}
 67→
 68→/// Result of executing a step.
 69→#[derive(Debug)]
 70→pub struct StepResult {
 71→    /// Step name.
 72→    pub name: String,
 73→
 74→    /// Whether the step succeeded.
 75→    pub success: bool,
 76→
 77→    /// Execution duration.
 78→    pub duration: Duration,
 79→
 80→    /// Exit code (if command was run).
 81→    pub exit_code: Option<i32>,
 82→
 83→    /// Whether step was skipped (already complete).
 84→    pub skipped: bool,
 85→
 86→    /// Completion check result (if run).
 87→    pub check_result: Option<CheckResult>,
 88→
 89→    /// Error message (if failed).
 90→    pub error: Option<String>,
 91→
 92→    /// Captured output (if available).
 93→    pub output: Option<String>,
 94→
 95→    /// Recovery detail (e.g., "succeeded on retry (attempt 2)", "skipped by user").
 96→    pub recovery_detail: Option<String>,
 97→}
 98→
 99→impl StepResult {
100→    /// Create a skipped result.
101→    pub fn skipped(name: &str, check_result: CheckResult) -> Self {
102→        Self {
103→            name: name.to_string(),
104→            success: true,
105→            duration: Duration::ZERO,
106→            exit_code: None,
107→            skipped: true,
108→            check_result: Some(check_result),
109→            error: None,
110→            output: None,
111→            recovery_detail: None,
112→        }
113→    }
114→
115→    /// Create a success result.
116→    pub fn success(
117→        name: &str,
118→        duration: Duration,
119→        exit_code: Option<i32>,
120→        output: Option<String>,
121→    ) -> Self {
122→        Self {
123→            name: name.to_string(),
124→            success: true,
125→            duration,
126→            exit_code,
127→            skipped: false,
128→            check_result: None,
129→            error: None,
130→            output,
131→            recovery_detail: None,
132→        }
133→    }
134→
135→    /// Create a failure result.
136→    pub fn failure(name: &str, duration: Duration, error: String, output: Option<String>) -> Self {
137→        Self {
138→            name: name.to_string(),
139→            success: false,
140→            duration,
141→            exit_code: None,
142→            skipped: false,
143→            check_result: None,
144→            error: Some(error),
145→            output,
146→            recovery_detail: None,
147→        }
148→    }
149→
150→    /// Get the status of this result.
151→    pub fn status(&self) -> StepStatus {
152→        if self.skipped {
153→            StepStatus::Skipped
154→        } else if self.success {
155→            StepStatus::Completed
156→        } else {
157→            StepStatus::Failed
158→        }
159→    }
160→
161→    /// Generate a summary line for display.
162→    pub fn summary_line(&self) -> String {
163→        let status = self.status();
164→        let duration_str = format_duration(self.duration);
165→
166→        match status {
167→            StepStatus::Completed => {
168→                format!("{} {} ({})", status.display_char(), self.name, duration_str)
169→            }
170→            StepStatus::Skipped => {
171→                let reason = self
172→                    .check_result
173→                    .as_ref()
174→                    .map(|c| c.short_description())
175→                    .unwrap_or("already complete");
176→                format!("{} {} ({})", status.display_char(), self.name, reason)
177→            }
178→            StepStatus::Failed => {
179→                let error = self.error.as_deref().unwrap_or("unknown error");
180→                format!("{} {} - {}", status.display_char(), self.name, error)
181→            }
182→            _ => format!("{} {}", status.display_char(), self.name),
183→        }
184→    }
185→}
186→
187→fn format_duration(duration: Duration) -> String {
188→    let secs = duration.as_secs();
189→    let millis = duration.subsec_millis();
190→
191→    if secs == 0 {
192→        format!("{}ms", millis)
193→    } else if secs < 60 {
194→        format!("{}.{}s", secs, millis / 100)
195→    } else {
196→        let mins = secs / 60;
197→        let secs = secs % 60;
198→        format!("{}m {}s", mins, secs)
199→    }
200→}

  1→//! Cache storage implementation.
  2→
  3→use anyhow::{Context, Result};
  4→use sha2::{Digest, Sha256};
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→
  8→use super::entry::CacheEntry;
  9→
 10→/// Storage for cached templates.
 11→pub struct CacheStore {
 12→    /// Root directory for cache.
 13→    root: PathBuf,
 14→}
 15→
 16→impl CacheStore {
 17→    /// Create a new cache store.
 18→    pub fn new(root: impl Into<PathBuf>) -> Self {
 19→        Self { root: root.into() }
 20→    }
 21→
 22→    /// Get the cache root directory.
 23→    pub fn root(&self) -> &Path {
 24→        &self.root
 25→    }
 26→
 27→    /// Ensure the cache directory exists.
 28→    fn ensure_dir(&self) -> Result<()> {
 29→        fs::create_dir_all(&self.root)
 30→            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
 31→    }
 32→
 33→    /// Get the path for storing an entry's content.
 34→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 35→        let key = format!("{}:{}", source_id, template_name);
 36→        let hash = Sha256::digest(key.as_bytes());
 37→        let hash_str = hex::encode(&hash[..16]);
 38→        self.root.join(hash_str)
 39→    }
 40→
 41→    /// Get the metadata file path for an entry.
 42→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 43→        self.content_path(source_id, template_name)
 44→            .with_extension("meta.json")
 45→    }
 46→
 47→    /// Store content and return a cache entry.
 48→    pub fn store(
 49→        &self,
 50→        source_id: &str,
 51→        template_name: &str,
 52→        content: &str,
 53→        ttl_seconds: u64,
 54→    ) -> Result<CacheEntry> {
 55→        self.ensure_dir()?;
 56→
 57→        let content_path = self.content_path(source_id, template_name);
 58→        fs::write(&content_path, content)?;
 59→
 60→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 61→            .with_size(content.len() as u64);
 62→
 63→        self.save_metadata(&entry)?;
 64→
 65→        Ok(entry)
 66→    }
 67→
 68→    /// Load a cached entry's metadata.
 69→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 70→        let meta_path = self.metadata_path(source_id, template_name);
 71→
 72→        if !meta_path.exists() {
 73→            return Ok(None);
 74→        }
 75→
 76→        let json = fs::read_to_string(&meta_path)?;
 77→        let entry: CacheEntry = serde_json::from_str(&json)?;
 78→
 79→        Ok(Some(entry))
 80→    }
 81→
 82→    /// Read the cached content.
 83→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
 84→        fs::read_to_string(&entry.content_path).with_context(|| {
 85→            format!(
 86→                "Failed to read cached content from {:?}",
 87→                entry.content_path
 88→            )
 89→        })
 90→    }
 91→
 92→    /// Save entry metadata.
 93→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
 94→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
 95→        let json = serde_json::to_string_pretty(entry)?;
 96→        fs::write(&meta_path, json)?;
 97→        Ok(())
 98→    }
 99→
100→    /// Update an entry's metadata (e.g., after revalidation).
101→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
102→        self.save_metadata(entry)
103→    }
104→
105→    /// Remove a cached entry.
106→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
107→        let content_path = self.content_path(source_id, template_name);
108→        let meta_path = self.metadata_path(source_id, template_name);
109→
110→        let mut removed = false;
111→
112→        if content_path.exists() {
113→            fs::remove_file(&content_path)?;
114→            removed = true;
115→        }
116→
117→        if meta_path.exists() {
118→            fs::remove_file(&meta_path)?;
119→            removed = true;
120→        }
121→
122→        Ok(removed)
123→    }
124→
125→    /// List all cached entries.
126→    pub fn list(&self) -> Result<Vec<CacheEntry>> {
127→        self.ensure_dir()?;
128→
129→        let mut entries = Vec::new();
130→
131→        for entry in fs::read_dir(&self.root)? {
132→            let entry = entry?;
133→            let path = entry.path();
134→
135→            if path.extension().is_some_and(|e| e == "json") {
136→                if let Ok(json) = fs::read_to_string(&path) {
137→                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
138→                        entries.push(cache_entry);
139→                    }
140→                }
141→            }
142→        }
143→
144→        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
145→        Ok(entries)
146→    }
147→
148→    /// Clear all cached entries.
149→    pub fn clear(&self) -> Result<usize> {
150→        let entries = self.list()?;
151→        let count = entries.len();
152→
153→        for entry in entries {
154→            let _ = self.remove(&entry.source_id, &entry.template_name);
155→        }
156→
157→        Ok(count)
158→    }
159→
160→    /// Get total cache size in bytes.
161→    pub fn total_size(&self) -> Result<u64> {
162→        let entries = self.list()?;
163→        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
164→    }
165→}
